1	/**
2	 * Página standalone de separação por bip — carrega a active_session pelo id
3	 * e abre o SeparacaoBipModal com seus items.
4	 */
5	import { useEffect, useState } from "react";
6	import { useNavigate, useParams } from "react-router-dom";
7	import { supabase } from "@/integrations/supabase/client";
8	import { SeparacaoBipModal } from "./SeparacaoBipModal";
9	import { Card, CardContent } from "@/shared/ui/card";
10	import { Button } from "@/shared/ui/button";
11	import { ArrowLeft, AlertTriangle } from "lucide-react";
12	import { Skeleton } from "@/shared/ui/skeleton";
13	import { useStore } from "@/shared/contexts/StoreContext";
14	
15	interface SessionRow {
16	  session_id: string;
17	  preparer_name: string;
18	  store_preparer: string;
19	  status: string;
20	}
21	
22	interface ItemRow {
23	  id: string;
24	  item_name: string;
25	  requested_quantity: number;
26	  is_separated: boolean;
27	  qr_uid_bipado?: string | null;
28	  produto_master_id?: number | null;
29	  unidade_medida?: string | null;
30	}
31	
32	export default function SeparacaoBipPage() {
33	  const { sessionId } = useParams<{ sessionId: string }>();
34	  const navigate = useNavigate();
35	  const { selectedStore } = useStore();
36	  const [session, setSession] = useState<SessionRow | null>(null);
37	  const [items, setItems] = useState<ItemRow[]>([]);
38	  const [loading, setLoading] = useState(true);
39	  const [erro, setErro] = useState<string | null>(null);
40	
41	  useEffect(() => {
42	    if (!sessionId) return;
43	    let cancelled = false;
44	    setLoading(true);
45	    setErro(null);
46	
47	    Promise.all([
48	      supabase.from("active_sessions").select("session_id, preparer_name, store_preparer, status").eq("session_id", sessionId).maybeSingle(),
49	      // eslint-disable-next-line @typescript-eslint/no-explicit-any
50	      (supabase.from("active_session_items") as any)
51	        .select("id, item_name, requested_quantity, is_separated, qr_uid_bipado, produto_master_id, unidade_medida")
52	        .eq("session_id", sessionId)
53	        .order("order_index"),
54	    ]).then(([sRes, iRes]) => {
55	      if (cancelled) return;
56	      if (sRes.error || !sRes.data) {
57	        setErro(sRes.error?.message || "Sessão não encontrada");
58	        setLoading(false);
59	        return;
60	      }
61	      setSession(sRes.data as SessionRow);
62	      const itemsData = (iRes.data ?? []) as ItemRow[];
63	      setItems(itemsData);
64	      setLoading(false);
65	    });
66	
67	    return () => {
68	      cancelled = true;
69	    };
70	  }, [sessionId]);
71	
72	  if (loading) {
73	    return (
74	      <div className="p-4 sm:p-8 max-w-3xl mx-auto space-y-4">
75	        <Skeleton className="h-12 w-48" />
76	        <Skeleton className="h-64 w-full" />
77	      </div>
78	    );
79	  }
80	
81	  if (erro || !session) {
82	    return (
83	      <div className="p-4 sm:p-8 max-w-2xl mx-auto">
84	        <Button variant="ghost" size="sm" onClick={() => navigate(-1)} className="gap-2 mb-4 min-h-[44px]">
85	          <ArrowLeft className="w-4 h-4" /> Voltar
86	        </Button>
87	        <Card className="border-red-200">
88	          <CardContent className="p-4 sm:p-6 flex items-start gap-3 text-red-700">
89	            <AlertTriangle className="w-5 h-5 flex-shrink-0 mt-0.5" />
90	            <div className="min-w-0">
91	              <p className="font-bold">{erro || "Sessão de separação não encontrada"}</p>
92	              <p className="text-sm text-muted-foreground break-all">ID: {sessionId}</p>
93	            </div>
94	          </CardContent>
95	        </Card>
96	      </div>
97	    );
98	  }
99	
100	  return (
101	    <SeparacaoBipModal
102	      isOpen
103	      onClose={() => navigate(-1)}
104	      sessionId={session.session_id}
105	      sessionLabel={`${session.store_preparer || "—"} → preparado por ${session.preparer_name || "—"}`}
106	      items={items.map((i) => ({
107	        id: i.id,
108	        item_name: i.item_name,
109	        requested_quantity: i.requested_quantity,
110	        is_separated: i.is_separated,
111	        produto_master_id: i.produto_master_id ?? null,
112	        qr_uid_bipado: i.qr_uid_bipado ?? null,
113	        unidade_medida: i.unidade_medida ?? 'cx',
114	      }))}
115	      lojaPreparadoraId={selectedStore?.id ?? null}
116	      defaultMode={typeof navigator !== "undefined" && /Android|iPad|iPhone|Mobile|Tablet/i.test(navigator.userAgent) ? "camera" : "bluetooth"}
117	    />
118	  );
119	}
