136	function startOfWeek(date = new Date()) {
137	  const d = new Date(date);
138	  const day = d.getDay();
139	  const diff = (day === 0 ? -6 : 1) - day; // segunda-feira
140	  d.setDate(d.getDate() + diff);
141	  d.setHours(0, 0, 0, 0);
142	  return d;
143	}
144	
145	function formatDateISO(d: Date) {
146	  const y = d.getFullYear();
147	  const m = String(d.getMonth() + 1).padStart(2, '0');
148	  const day = String(d.getDate()).padStart(2, '0');
149	  return `${y}-${m}-${day}`;
150	}
151	
152	function buildDays(from: Date, count: number) {
153	  const days: { key: string; date: Date; dateISO: string; label: string }[] =
154	    [];
155	  for (let i = 0; i < count; i++) {
156	    const d = new Date(from);
157	    d.setDate(from.getDate() + i);
158	    const weekday = d.toLocaleDateString('pt-BR', {
159	      timeZone: 'America/Sao_Paulo',
160	      weekday: 'short',
161	    });
162	    const label = `${weekday} ${d.toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit' })}`;
163	    days.push({
164	      key: `${formatDateISO(d)}-${i}`,
165	      date: d,
166	      dateISO: formatDateISO(d),
167	      label,
168	    });
169	  }
170	  return days;
171	}
172	
173	function dateISOForReq(r: RequisicaoQueue) {
174	  // Priorizar sempre a data de recebimento para agrupamento, depois data do pedido
175	  // O título pode conter uma data (byName), mas é apenas rótulo
176	  const byName = dateISOFromName(r.nome);
177	  const iso =
178	    r.data_recebimento || r.data_pedido || byName || r.created_at.slice(0, 10);
179	  return iso;
180	}
