265	function ReqCard({
266	  req,
267	  displayDateISO,
268	  onClick,
269	  factoryName = 'Fábrica',
270	  isMobile,
271	}: {
272	  req: RequisicaoQueue;
273	  displayDateISO?: string;
274	  onClick: () => void;
275	  factoryName?: string;
276	  isMobile?: boolean;
277	}) {
278	  const itens = req.requisicoes_itens || [];
279	  const createdSource = (() => {
280	    const s = String(req.created_at || '');
281	    const hasTime = /[T\s]\d{2}:\d{2}/.test(s);
282	    if (hasTime) return s;
283	    const itTs = String(itens[0]?.created_at || '');
284	    return itTs || s;
285	  })();
286	  const createdTime = formatTime(createdSource);
287	  const entrega = parseISODateLocal(
288	    displayDateISO || req.data_recebimento || req.data_pedido,
289	  );
290	  const entregaDia = entrega.toLocaleDateString('pt-BR', {
291	    timeZone: 'America/Sao_Paulo',
292	    weekday: 'short',
293	  });
294	  const entregaData = entrega.toLocaleDateString('pt-BR', {
295	    timeZone: 'America/Sao_Paulo',
296	    day: '2-digit',
297	    month: '2-digit',
298	  });
299	
300	  const normalizedStatus = normalizeRequisicaoStatus(req.status);
301	  // Mapeamento direto do status do banco para o status visual
302	  // em_fila -> aberta (azul)
303	  // em_progresso -> progresso (laranja)
304	  // finalizada -> finalizada (verde)
305	  const status: 'aberta' | 'progresso' | 'finalizada' =
306	    normalizedStatus === 'finalizada'
307	      ? 'finalizada'
308	      : normalizedStatus === 'em_progresso'
309	        ? 'progresso'
310	        : 'aberta';
311	
312	  const nameDateISO = coerceISODateString(
313	    displayDateISO || req.data_recebimento || req.data_pedido || '',
314	  );
315	  const nameDateLabel = formatDateDDMMYY(nameDateISO);
316	  const displayName = `Requisição - ${req.loja_solicitante} - ${nameDateLabel}`;
317	
318	  // ─── MIA selector ──────────────────────────────────────────
319	  // Permite MIA identificar e clicar em uma requisição específica
320	  // via: "abrir requisição asa norte de hoje" → data-mia-action
321	  // resolve por (loja_slug, data_iso).
322	  const lojaSlug = (req.loja_solicitante || '')
323	    .toString()
324	    .toLowerCase()
325	    .normalize('NFD')
326	    .replace(/[̀-ͯ]/g, '')
327	    .replace(/[^a-z0-9]+/g, '-')
328	    .replace(/^-+|-+$/g, '');
329	  const miaAction = `abrir-requisicao-${lojaSlug}-${nameDateISO}`;
330	
331	  const statusStyles = {
332	    finalizada: {
333	      barGradient: 'from-emerald-500 to-emerald-400',
334	      dotColor: 'bg-emerald-500',
335	      badge: 'bg-emerald-50 text-emerald-700 border-emerald-200 dark:bg-emerald-900/30 dark:text-emerald-300 dark:border-emerald-800/50',
336	      badgeLabel: 'Finalizada',
337	      glow: 'hover:shadow-[0_8px_30px_rgba(16,185,129,0.18)]',
338	      accentOverlay: 'from-emerald-500/[0.04] via-transparent to-transparent',
339	    },
340	    progresso: {
341	      barGradient: 'from-amber-500 to-orange-400',
342	      dotColor: 'bg-amber-500',
343	      badge: 'bg-amber-50 text-amber-700 border-amber-200 dark:bg-amber-900/30 dark:text-amber-300 dark:border-amber-800/50',
344	      badgeLabel: 'Em Progresso',
345	      glow: 'hover:shadow-[0_8px_30px_rgba(245,158,11,0.18)]',
346	      accentOverlay: 'from-amber-500/[0.04] via-transparent to-transparent',
347	    },
348	    aberta: {
349	      barGradient: 'from-sky-500 to-blue-400',
350	      dotColor: 'bg-sky-500',
351	      badge: 'bg-sky-50 text-sky-700 border-sky-200 dark:bg-sky-900/30 dark:text-sky-300 dark:border-sky-800/50',
352	      badgeLabel: 'Na Fila',
353	      glow: 'hover:shadow-[0_8px_30px_rgba(96,165,250,0.18)]',
354	      accentOverlay: 'from-sky-500/[0.04] via-transparent to-transparent',
355	    },
356	  }[status];
357	
358	  return (
359	    <button
360	      data-mia-action={miaAction}
361	      data-mia-loja={req.loja_solicitante}
362	      data-mia-data={nameDateISO}
363	      data-mia-status={status}
364	      data-mia-req-id={req.id}
365	      aria-label={displayName}
366	      onClick={onClick}
367	      className={classNames(
368	        'group relative w-full text-left rounded-xl overflow-hidden transition-all duration-300',
369	        'bg-white/95 dark:bg-zinc-900/70 backdrop-blur-xl',
370	        'border border-zinc-200/80 dark:border-white/10',
371	        'shadow-[0_1px_3px_rgba(0,0,0,0.04),0_2px_8px_rgba(0,0,0,0.04)] hover:-translate-y-0.5 hover:border-zinc-300 dark:hover:border-white/20',
372	        statusStyles.glow,
373	        isMobile ? 'min-h-[100px]' : 'min-h-[120px]',
374	      )}
375	    >
376	      {/* Status bar lateral */}
377	      <div
378	        className={classNames(
379	          'absolute left-0 top-0 bottom-0 w-1 bg-gradient-to-b',
380	          statusStyles.barGradient,
381	        )}
382	      />
383	
384	      {/* Soft gradient overlay */}
385	      <div
386	        className={classNames(
387	          'absolute inset-0 pointer-events-none bg-gradient-to-br',
388	          statusStyles.accentOverlay,
389	        )}
390	      />
391	
392	      {/* Conteúdo */}
393	      <div className={classNames('relative z-10', isMobile ? 'pl-3 pr-3 py-2.5' : 'pl-4 pr-3 py-3')}>
394	        {/* Header: loja origem → destino + badge */}
395	        <div className="flex items-start justify-between gap-2 mb-2">
396	          <div className="flex items-center gap-1.5 min-w-0 flex-1">
397	            <Truck className="w-3 h-3 text-[#57715B] dark:text-emerald-400 flex-shrink-0" />
398	            <span className="text-[10px] font-semibold uppercase tracking-wider text-muted-foreground truncate">
399	              {factoryName} → {req.loja_solicitante}
400	            </span>
401	          </div>
402	          <span
403	            className={classNames(
404	              'inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[9px] font-bold uppercase tracking-wider border flex-shrink-0',
405	              statusStyles.badge,
