17	import { ScrollArea } from "@/shared/ui/scroll-area";
18	import { Bluetooth, Camera, ScanBarcode, ArrowLeft, CheckCircle2, XCircle, Package, AlertTriangle } from "lucide-react";
19	import { toast } from "sonner";
20	import { cn } from "@/shared/lib/utils";
21	import { supabase } from "@/integrations/supabase/client";
22	import { useEtiquetaScanner, playSuccessSound, playWarningSound, playErrorSound, formatBipError, calcularIncrementoBip, type ScannedPayload } from "@/shared/hooks/useEtiquetaScanner";
23	import { CameraScannerStatus } from "./CameraScannerStatus";
24	
25	interface SessionItem {
26	  id: string;
27	  item_name: string;
28	  requested_quantity: number;
29	  is_separated: boolean;
30	  produto_master_id?: number | null;
31	  qr_uid_bipado?: string | null;
32	  /** Unidade do item (cx, kg, g, l, ml…). Default 'cx' se vazio. */
33	  unidade_medida?: string | null;
34	}
35	
36	interface BipSlot {
37	  slotId: string;
38	  itemId: string;
39	  itemName: string;
40	  produtoMasterId: number | null;
41	  slotIndex: number;
42	  totalSlots: number;
43	  status: "pending" | "confirmed" | "extra";
44	  uid?: string;
45	  payload?: ScannedPayload;
46	  bipadoAt?: number;
47	  /** Unidades dentro da caixa (preenchido ao bipar) */
48	  qtyInterna?: number;
49	  embalagem?: string | null;
50	  // Bulk = 1 slot único pro item inteiro (ex: "10 kg"). Senão = N slots discretos.
51	  isBulkUnit?: boolean;
52	  unidadeMedida?: string;
53	  bulkQty?: number;
54	}
55	
56	// Bulk = 1 etiqueta cobre a quantidade total. Inclui peso/volume contínuo
57	// E containers de volume fixo (balde, galão, tambor, barril, garrafa).
58	const BULK_UNITS = new Set([
59	  'kg', 'g', 'l', 'litro', 'litros', 'ml', 'liter', 'liters',
60	  'balde', 'baldes', 'galao', 'galão', 'galões', 'galoes',
61	  'tambor', 'tambores', 'barril', 'barris', 'garrafa', 'garrafas'
62	]);
63	const isBulkMeasure = (u: string | null | undefined) => BULK_UNITS.has((u || '').toLowerCase().trim());
64	
65	interface Props {
66	  isOpen: boolean;
67	  onClose: () => void;
68	  sessionId: string;
69	  sessionLabel: string;
70	  items: SessionItem[];
71	  lojaPreparadoraId: number | null;
72	  onItemSeparated?: (itemId: string, uid: string) => void;
73	  /** Modo padrão do scanner: fábrica usa "bluetooth", loja usa "camera". */
74	  defaultMode?: "bluetooth" | "camera";
75	}
76	
77	function buildSlots(items: SessionItem[]): BipSlot[] {
78	  const out: BipSlot[] = [];
79	  items.forEach((item) => {
80	    const unit = item.unidade_medida || 'cx';
81	    if (isBulkMeasure(unit)) {
82	      // Bulk: 1 slot único representa o pedido inteiro (ex: "10 kg" = 1 bip)
83	      const bulkQty = Number(item.requested_quantity) || 1;
84	      out.push({
85	        slotId: `${item.id}-bulk`,
86	        itemId: item.id,
87	        itemName: item.item_name,
88	        produtoMasterId: item.produto_master_id ?? null,
89	        slotIndex: 1,
90	        totalSlots: 1,
91	        status: item.is_separated ? "confirmed" : "pending",
92	        uid: item.qr_uid_bipado || undefined,
93	        isBulkUnit: true,
94	        unidadeMedida: unit,
95	        bulkQty,
96	      });
97	      return;
98	    }
99	    // Box: N slots discretos (1 etiqueta por caixa/unidade)
100	    const total = Math.max(1, Math.round(item.requested_quantity || 1));
101	    for (let i = 1; i <= total; i++) {
102	      out.push({
103	        slotId: `${item.id}-slot-${i}`,
104	        itemId: item.id,
105	        itemName: item.item_name,
106	        produtoMasterId: item.produto_master_id ?? null,
107	        slotIndex: i,
108	        totalSlots: total,
109	        status: item.is_separated && i === 1 ? "confirmed" : "pending",
110	        uid: item.qr_uid_bipado || undefined,
111	        unidadeMedida: unit,
112	      });
113	    }
114	  });
115	  return out;
116	}
