149	          return null;
150	        }
151	      }
152	
153	      // Telemetria — requisição criada com sucesso
154	      recordRequisition(items.length, { 'session.id': session.session_id, 'store.requester': storeRequester, 'store.preparer': storePreparer });
155	      wideInfo('requisicao.criar', 'Requisição criada com sucesso', { domain: 'requisicao', attributes: { 'session.id': session.session_id, 'requisicao.item_count': items.length, 'store.requester': storeRequester, 'store.preparer': storePreparer, 'store.name': storeRequester } });
156	
157	      setCurrentSession(session);
158	      toast.success('Sessão ativa criada com sucesso!');
159	      return session as ActiveSessionData;
160	    } catch (error) {
