162	      recordError('REQUISICAO_CREATE_FAILED', 'UnexpectedError', { 'error.message': error instanceof Error ? error.message : String(error) });
163	      wideError('requisicao.criar', 'Erro inesperado ao criar sessão', { domain: 'requisicao', attributes: { 'error.message': error instanceof Error ? error.message : String(error), 'operation.name': 'createSession' } });
